/* 食事帯(meal): 朝/昼/夜 のうち、そのレシピが向く帯。将来の朝/昼/夜ごとの献立生成で使う。
 * 既定は cat から推定(副菜・汁物=朝昼夜、それ以外=昼夜)。MEAL はそれと異なるものだけ上書きする。 */
function defaultMeal(r) {
  if (r.cat === "副菜" || r.cat === "汁物") return ["朝", "昼", "夜"];
  return ["昼", "夜"];
}
const MEAL = {
  // 朝食向け(新規)
  medamayaki: ["朝", "昼"], hamegg: ["朝", "昼"], scrambledegg: ["朝", "昼"],
  nattogohan: ["朝"], tamagokake: ["朝"], buttertoast: ["朝"], frenchtoast: ["朝"], pancake: ["朝", "昼"],
  ochazuke: ["朝", "夜"], yakionigiri: ["朝", "昼"], tamagosando: ["朝", "昼"], tunamelt: ["朝", "昼"], smoothie: ["朝"],
  // 昼向け(軽食・麺)
  hiyashichuka: ["昼"], zarusoba: ["昼"], shirasudon: ["朝", "昼"],
  // 既存の上書き(朝にも合う / 夜には主菜として出さない)
  shiozake: ["朝", "昼", "夜"], onigiri: ["朝", "昼", "夜"], pizzatoast: ["朝", "昼"], fruityogurt: ["朝", "昼"],
};
RECIPES.forEach(function (r) { r.meal = MEAL[r.id] || defaultMeal(r); });

if (typeof module !== "undefined" && module.exports) module.exports = RECIPES;
